import{_ as t,o as a,c as l,a2 as i}from"./chunks/framework.RQXGjTIX.js";const p=JSON.parse('{"title":"安装与版本","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),r={name:"guide/install.md"};function d(o,e,c,n,s,h){return a(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="安装与版本" tabindex="-1">安装与版本 <a class="header-anchor" href="#安装与版本" aria-label="Permalink to &quot;安装与版本&quot;">​</a></h1><h2 id="前置版本" tabindex="-1">前置版本 <a class="header-anchor" href="#前置版本" aria-label="Permalink to &quot;前置版本&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组件</th><th>版本</th></tr></thead><tbody><tr><td>Minecraft</td><td>1.21.1</td></tr><tr><td>NeoForge</td><td>21.1.251 或更高（21.1.x）</td></tr><tr><td>Applied Energistics 2</td><td>19.2.x</td></tr><tr><td>Create</td><td>6.0.10.x</td></tr><tr><td>Create: Crafted Beginning</td><td>0.1.x（0.1.1 已验证；0.1.2 源码改过气体网络调度，公开 API 未变，发布后需回归）</td></tr><tr><td>Applied Crafted Energistics</td><td>0.2.x</td></tr></tbody></table><p>以上版本范围也写进了模组的 <code>neoforge.mods.toml</code>，版本不符时加载器会直接提示。</p><h2 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h2><ol><li>安装 <strong>NeoForge 1.21.1</strong>（≥ 21.1.251）；</li><li>把以下四个 jar 放进整合包的 <code>mods/</code> 目录： <ul><li><code>appliedenergistics2-19.2.x.jar</code></li><li><code>create-1.21.1-6.0.10.x.jar</code></li><li><code>createcraftedbeginning-0.1.x.jar</code></li><li><code>appliedcraftedenergistics-1.21.1-neoforge-0.2.0.jar</code></li></ul></li><li>启动游戏。</li></ol><blockquote><p>本模组是纯附属，不需要新建世界、不需要额外资源包，也没有客户端 / 服务端分离的额外要求； 服务端需要与客户端安装同样的四个模组。</p></blockquote><h2 id="版本与下载" tabindex="-1">版本与下载 <a class="header-anchor" href="#版本与下载" aria-label="Permalink to &quot;版本与下载&quot;">​</a></h2><ul><li>发布页：<a href="https://github.com/DaKang233/AppliedCraftedEnergistics/releases" target="_blank" rel="noreferrer">GitHub Releases</a></li><li>当前版本 <code>0.2.0</code> 的文件校验： <ul><li>大小 213,915 字节</li><li>SHA-256 <code>A24AC6BC13A4D47E5EB782CA9F5E72642A172EC9998199FF0BDA93F92676B4DB</code></li></ul></li></ul><h2 id="从-0-1-x-升级到-0-2-0" tabindex="-1">从 0.1.x 升级到 0.2.0 <a class="header-anchor" href="#从-0-1-x-升级到-0-2-0" aria-label="Permalink to &quot;从 0.1.x 升级到 0.2.0&quot;">​</a></h2><ul><li>旧接口 8 kL 缓冲罐中的气体会自动转入新接口的第一个空槽；</li><li>旧的单设备模式与供给压力设置不再使用，改为逐槽设置；</li><li>原版 <code>ae2:interface</code> 不再提供气体缓存能力。</li></ul><h2 id="升级注意" tabindex="-1">升级注意 <a class="header-anchor" href="#升级注意" aria-label="Permalink to &quot;升级注意&quot;">​</a></h2><ul><li><strong>先完全退出游戏，再替换 <code>mods/</code> 里的 jar</strong>。 在游戏运行中覆盖 jar 会导致打开的文件与磁盘内容错位，之后任何一次懒加载都会抛 <code>NoClassDefFoundError</code>（表现为&quot;玩一段时间后崩溃在某个方块实体上&quot;）。</li><li>替换后重启游戏即可；世界存档不需要迁移。</li></ul><h2 id="验证安装是否成功" tabindex="-1">验证安装是否成功 <a class="header-anchor" href="#验证安装是否成功" aria-label="Permalink to &quot;验证安装是否成功&quot;">​</a></h2><p>进入游戏后，如果模组加载正常：</p><ul><li>创造模式物品栏里能看到&quot;气体存储元件&quot;等物品；</li><li>任意物品栏界面按 <code>G</code> 能打开 GuideME 教程；</li><li><code>logs/latest.log</code> 里会出现两行以 <code>Applied Crafted Energistics:</code> 开头的日志。</li></ul>',16)])])}const f=t(r,[["render",d]]);export{p as __pageData,f as default};
